begin;
update public.characters set definition='{"deckType":"continuous","role":"매 턴 새로운 두 장으로 승부하는 도박사","icon":"⚄","color":"#ffd078","attackFx":"dice","attackSfx":"sfx_attack_gambler","skill":{"id":"random_hand","name":"운명의 패","type":"passive","description":"매 턴 1~7 두 장을 새로 뽑습니다. 6·7 제출 후 관망: 1~5 중 직전 손패를 제외한 서로 다른 두 장을 뽑습니다. 관망 중 중복되면 다음 턴 운명의 패로 복귀. 사이클 없음."},"randomDeck":{"min":1,"max":7,"count":2},"balanceRevision":3}'::jsonb where id='gambler';
update public.characters set definition='{"deckType":"fixed","role":"세 발의 탄환을 쏟아내는 사수","icon":"⌖","color":"#ffd08a","attackFx":"bullet","attackSfx":"sfx_attack_gunner","skill":{"id":"full_burst","name":"전탄발사","type":"hybrid","description":"손패는 1/2/3 세 장. 2사이클마다 1회 발동: 선택 카드가 중복되지 않으면 남은 손패를 모두 합산해 사용하고 새 사이클로 진입합니다. 성공 후 2사이클 뒤, 중복 실패 후 다음 사이클에 재사용 가능합니다."},"balanceRevision":3}'::jsonb where id='gunner';
update public.characters set definition='{"deckType":"fixed","role":"이어지는 권격으로 적을 압도하는 격투가","icon":"✊","color":"#ffac78","attackFx":"fist","attackSfx":"sfx_attack_fighter","skill":{"id":"combo","name":"연격","type":"passive","description":"몬스터 전투에서 직전 카드보다 높은 카드로 공격 성공 시 연격 +1(최대 3). 공격에 연격만큼 추가 피해. 중복 또는 몬스터 처치 시 중첩이 초기화됩니다. 전투 중 중복 실패 시 -1점."},"balanceRevision":3}'::jsonb where id='fighter';
update public.characters set definition='{"deckType":"fixed","role":"위험할수록 강해지는 공격수","icon":"⚒","color":"#ff766d","attackFx":"axe","attackSfx":"sfx_attack_berserker","skill":{"id":"blood_heat","name":"피의 열기","type":"passive","description":"중복 시 HP 1 회복(이 회복은 HP 2까지만). 기절 시 추가 -3점. 유효 공격 효과 +1, 명중 시 HP 1 소모(최소 HP 1). 중복 판정은 원래 숫자이며 비전투 효과에는 +1이 적용되지 않습니다."},"balanceRevision":3}'::jsonb where id='berserker';
commit;
